// Transcribed from solid-js@2.0.0-rc.3, the prerelease this repository audits.
//
// Every name here is re-exported by `solid-js`' own `types/index.d.ts:1` from
// `@solidjs/signals`, so a `solid-js` import resolves to these declarations.
// Each is byte-faithful to `@solidjs/signals@2.0.0-rc.3`:
//
// - `untrack`        `dist/types/core/core.d.ts:75`
// - `runWithOwner`   `dist/types/core/core.d.ts:141`
// - `createRoot`     `dist/types/core/owner.d.ts:121-124`
// - `onCleanup`      `dist/types/signals.d.ts:41`
// - `createEffect`   `dist/types/signals.d.ts:367`
// - `Disposable`     `dist/types/core/types.d.ts:4-6`
//
// Nothing on the argument side is reduced. `untrack` keeps its second
// parameter, `createRoot` keeps the union that admits a `dispose`-taking
// callback, `runWithOwner` keeps the callback at index **1**, and `onCleanup`
// keeps `Disposable` on both sides -- these are the four shapes every claim in
// `expected.json` rests on. `createEffect` keeps the two-function form *and*
// the deprecated one-argument overload returning `never`, because dropping the
// second would make the negative pass for the wrong reason: `createEffect(fn)`
// must be a type error here exactly as it is against the published package.
//
// Reduced, and safe to reduce because no claim reads them back: the option
// objects' fields, `Owner`'s members, and the inference machinery
// (`NoInfer`, `EffectBundle`) around `createEffect`'s result.

export interface Disposable {
  (): void;
}

export interface Owner {
  readonly _parent: Owner | null;
}

export type ComputeFunction<Prev, Next extends Prev = Prev> = (previous: Prev) => Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (
  value: Next,
  previous: Prev
) => void | (() => void);

export interface EffectOptions {
  name?: string;
  defer?: boolean;
}

export declare function untrack<T>(fn: () => T, strictReadLabel?: string | false): T;

export declare function runWithOwner<T>(owner: Owner | null, fn: () => T): T;

export declare function createRoot<T>(
  init: ((dispose: () => void) => T) | (() => T),
  options?: {
    id?: string;
    transparent?: boolean;
  }
): T;

export declare function onCleanup(fn: Disposable): Disposable;

export declare function createEffect<T>(
  compute: ComputeFunction<undefined | T, T>,
  effectFn: EffectFunction<T, T>,
  options?: EffectOptions
): void;
/** @deprecated `createEffect(compute)` (single argument) is no longer supported. */
export declare function createEffect<T>(compute: ComputeFunction<undefined | T, T>): never;
